"""Distinct source episodes and teachings, never a quote assigned to every topic."""
from pathlib import Path
import json
R=Path(__file__).resolve().parent; cases=[]
def case(id,tradition,title,book,ref,kind,intents,example,story,teaching,apply,step,fit,uplift,url=''):
 cases.append(dict(id=id,tradition=tradition,title=title,book=book,reference=ref,source_kind=kind,intents=intents.split('|'),example=example,story=story,teaching=teaching,application=apply,step=step,why=fit,uplift=uplift,source_url=url,wording='Source-based retelling and original application; not a verbatim quotation.'))

case('rama-exile','Hinduism','Rama loses the future he expected','Valmiki Ramayana','Ayodhya Kanda, Sargas 18–19','Scripture narrative','role_loss|unfair_setback','My job ended and my plans have fallen apart.',
'Rama is preparing for coronation. Kaikeyi instead tells him that Bharata will rule and he must spend fourteen years in the forest. Rama is pained, but prepares to leave rather than turn his disappointment into a fight for the throne.',
'The episode shows a sudden loss of position without a loss of the ability to choose one’s conduct.',
'Losing a role can shake your identity. You can seek fair treatment and still decide what needs your care next. Rama’s response is an example, not a rule that you must accept injustice.',
'Name the most urgent change this loss creates. Choose one person who can help you deal with that change today.',
'The shared difficulty is a future changing suddenly, not the details of royal exile.',
'The path you expected can disappear without taking away your ability to choose the next step.',
'https://www.valmikiramayan.net/utf8/ayodhya/sarga19/ayodhyaroman19.htm')
case('hanuman-encouraged','Hinduism','Hanuman is reminded of his strength','Valmiki Ramayana','Kishkindha Kanda, Sargas 66–67','Scripture narrative','self_doubt|difficult_task','I do not think I can handle this responsibility.',
'The search party must cross the ocean to reach Lanka. Jambavan speaks to Hanuman about his strength and ability. With that encouragement, Hanuman declares what he can do and prepares for the leap.',
'Encouragement is connected to a real task and real abilities, not empty praise.',
'Instead of asking whether you are capable of everything, look at the skills this task actually needs. A trusted person may help you see evidence you are overlooking.',
'Ask someone who knows your work to name one strength you can use. Then choose the first part of the task.',
'This fits doubt about a demanding task, rather than grief or a broken relationship.',
'A difficult task can hide your confidence without erasing the abilities you already have.',
'https://www.valmikiramayan.net/utf8/kish/sarga67/kishkindharoman67.htm')
case('sudama-visit','Hinduism','Krishna welcomes Sudama with honour','Bhagavata Purana','Canto 10, Chapters 80–81','Scripture narrative','feeling_inferior|friendship_distance','I feel too unsuccessful to meet an old friend.',
'Sudama arrives at Krishna’s palace in poverty, carrying a small gift of rice. Krishna welcomes his old friend warmly and personally attends to him. Sudama’s poor clothing does not decide the respect he receives.',
'The friendship is presented through affection and hospitality rather than social rank.',
'If shame about money or status is making you hide, notice that it is a fear about how you will be received, not proof that you have no place in the friendship.',
'Send a simple message to a trusted old friend without apologising for your present status.',
'The shared issue is feeling lesser because another person appears more successful.',
'Your place in a true friendship need not be measured by what you can bring.',
'https://vedabase.io/en/library/sb/10/80/')
case('arjuna-conflict','Hinduism','Arjuna admits that he cannot decide','Bhagavad Gita','1:28–47; 2:7–10; 18:63','Teaching dialogue','conflicting_values','Two important duties pull me in different directions.',
'Seeing relatives and teachers on the battlefield, Arjuna becomes distressed and puts down his bow. He tells Krishna he is confused about duty and asks for guidance. Later, Krishna asks him to reflect on the teaching and then choose.',
'The dialogue begins with a clearly named moral conflict and a request for counsel, not a demand to stop feeling.',
'A career or family decision is not Arjuna’s battle. The useful method is to name the values in conflict, seek thoughtful counsel and make a considered choice.',
'Write the two values you are trying to protect. Ask a trusted adviser to help you examine the trade-off.',
'This fits conflict between values, not every situation involving work.',
'Asking for guidance can be part of a responsible decision, not a sign that you are weak.',
'https://www.holy-bhagavad-gita.org/chapter/2/verse/7')
case('dhruva-rejection','Hinduism','Dhruva turns rejection into a search','Bhagavata Purana','Canto 4, Chapter 8','Scripture narrative','family_rejection|feeling_inferior','Someone in my family makes me feel that I do not belong.',
'Dhruva is hurt when his stepmother rejects his attempt to approach his father. After speaking with his mother, he leaves on a spiritual search and receives guidance from Narada. His hurt becomes the starting point of a deeper search.',
'The story takes the child’s hurt seriously and introduces guidance rather than leaving him alone with it.',
'Another person’s rejection is not a complete measure of your worth. The modern application is to seek safe support, not to copy Dhruva’s departure or severe spiritual practices.',
'Tell a safe, trusted person what was said and how it affected you. Ask for the support you need.',
'This fits being made to feel lesser within a family.',
'Being denied a place by one person does not settle the value of your life.',
'https://vedabase.io/en/library/sb/4/8/')

case('jesus-gethsemane','Christianity','Jesus speaks honestly about fear','Bible','Mark 14:32–42','Scripture narrative','fear_ahead|difficult_task','I am frightened by something difficult I have to face.',
'In Gethsemane, Jesus tells his disciples that he is deeply distressed. He asks them to stay near while he prays about what lies ahead. The scene includes honest fear, a wish for companionship and continued prayer.',
'In this passage, deep distress and faith are present together.',
'You do not have to pretend to be calm before asking for help. Your circumstances differ from the Passion, but honest words and chosen support can help you face the next part.',
'Tell one trusted person what you are afraid of and ask for a specific kind of support.',
'The connection is fear before a difficult event, not a promise that the event will be removed.',
'Fear does not make your faith or courage unreal.',
'https://ebible.org/web/MRK14.htm')
case('peter-restored','Christianity','Peter is given responsibility after failure','Bible','John 18:15–27; 21:15–19','Scripture narrative','regret|second_chance','I made a mistake and feel I cannot begin again.',
'Peter denies knowing Jesus during the arrest and trial. After the resurrection, Jesus speaks with Peter, asks about his love and gives him responsibility to care for his followers. Peter’s failure is not the last scene of the relationship.',
'Restoration in the story includes renewed responsibility, not pretending that nothing happened.',
'A mistake can call for repair and changed behaviour without becoming your permanent identity.',
'Name one repair you can make safely and honestly. Commit to one action that shows what you will do differently.',
'This fits regret about your own actions, not blame for harm someone else caused you.',
'Your failure can be part of your story without becoming its final chapter.',
'https://ebible.org/web/JHN21.htm')
case('jesus-grieves','Christianity','Jesus weeps with those who are grieving','Bible','John 11:17–36','Scripture narrative','bereavement','Someone I love has died and I feel pressure to be strong.',
'Jesus meets Martha and Mary after Lazarus has died. He speaks with them, sees their grief and weeps. This happens before the later events of the chapter; the grief is not skipped.',
'The scene gives sorrow a place within faith and friendship.',
'You do not need to prove strength by hiding grief. The later miracle in the narrative is not a promise that a reader’s loss will be reversed.',
'Choose someone who can listen without rushing you. Tell them whether you want company, practical help or quiet.',
'This is about mourning a death, not ordinary disappointment.',
'Tears do not mean that your love, strength or faith has failed.',
'https://ebible.org/web/JHN11.htm')
case('samaritan-help','Christianity','Help comes from an unexpected neighbour','Bible','Luke 10:25–37','Parable told by Jesus','helping_someone|judged_by_group','I want to help someone but others say they are not one of us.',
'In Jesus’ parable, an injured traveller is passed by before a Samaritan stops. The Samaritan tends to him and arranges continued care. The answer to the question about a neighbour is expressed through practical mercy.',
'The parable places the person’s need ahead of an expected social boundary.',
'When it is safe to help, a useful action may matter more than deciding whether someone belongs to your group.',
'Ask what help is actually needed and what you can safely offer, rather than making a promise you cannot keep.',
'This fits a decision about practical help and prejudice; it is a parable, not an event Jesus claims happened to him.',
'Care can cross a boundary that prejudice tells you to keep.',
'https://ebible.org/web/LUK10.htm')
case('prodigal-return','Christianity','The younger son returns after his choices fail','Bible','Luke 15:11–32','Parable told by Jesus','regret|family_repair','I want to return to my family after making mistakes.',
'The younger son leaves home, spends his inheritance and reaches a point of need. He prepares to admit what he has done and returns. His father welcomes him, while the elder brother’s hurt also becomes part of the conversation.',
'The parable includes return, confession, welcome and a second family member’s unresolved feelings.',
'Repair may begin with an honest approach, while leaving room for the other person’s feelings. Real families are not required to respond exactly like the father in the parable.',
'Prepare a short apology that names your action and the repair you can offer, without demanding an immediate welcome.',
'This fits returning after your own mistake, not an obligation to return to an unsafe home.',
'An honest return can begin with responsibility rather than a perfect explanation.',
'https://ebible.org/web/LUK15.htm')

case('moses-speech','Judaism','Moses names the ability he doubts','Torah','Exodus 3:10–12; 4:10–17','Scripture narrative','self_doubt|speaking_fear','I have been asked to do something but I doubt my ability to speak.',
'When called to lead, Moses raises objections, including difficulty with speaking. The conversation does not simply ignore that concern: Aaron is named as someone who can speak alongside him.',
'The narrative joins a demanding calling with a concrete form of support.',
'It can help to name the exact part of a task you fear. A speech problem may need preparation or a partner, rather than a verdict that you cannot contribute.',
'Identify the part you can prepare and the person or tool that can support the part you find hardest.',
'This fits doubt about communication or a new responsibility.',
'Needing support does not mean you have nothing to offer.',
'https://ebible.org/web/EXO04.htm')
case('elijah-rest','Judaism','Elijah receives food and rest before the next journey','Tanakh','1 Kings 19:1–18','Scripture narrative','exhaustion','I am worn out and cannot face another demand.',
'After a threat, Elijah flees and reaches a point of deep despair. In the account, he sleeps and receives food and water before continuing to Horeb, where a further conversation follows.',
'The story attends to bodily needs before the next stage of responsibility.',
'When you are exhausted, the next step may be support and basic care rather than another demand to perform. Rest alone is not a cure for every cause of distress.',
'Choose one need you have been neglecting and ask for help with one demand that can wait.',
'This fits depletion and overload, rather than ordinary reluctance to begin a task.',
'Before asking yourself for another great effort, make room for the care you need.',
'https://ebible.org/web/1KI19.htm')
case('joseph-betrayal','Judaism','Joseph faces the brothers who betrayed him','Torah','Genesis 37:23–28; 42–45','Scripture narrative','betrayal|family_repair','My own family betrayed my trust.',
'Joseph’s brothers sell him away from home. Years later, when they come to Egypt for food, he does not reveal himself at once. The narrative includes testing, recognition and an emotional reunion.',
'Reconciliation in this story is a process, not a demand to restore trust instantly.',
'You can decide what safety and evidence of change you need before rebuilding trust. The story does not require you to return to a harmful relationship.',
'Separate forgiving feelings from practical trust. Write one boundary or sign of change you would need.',
'The shared issue is betrayal by close family, not a guarantee of Joseph’s later success.',
'You can leave room for a future without pretending that the betrayal did not happen.',
'https://ebible.org/web/GEN45.htm')
case('ruth-naomi','Judaism','Ruth stays beside Naomi through loss','Tanakh','Ruth 1:6–18','Scripture narrative','bereavement|supporting_grief','I do not know how to support someone who is grieving.',
'After deaths in the family, Naomi prepares to return to Judah and urges her daughters-in-law to go back to their own homes. Ruth chooses to stay with her and travel with her.',
'The scene presents loyalty as presence and a freely chosen commitment.',
'Supporting grief does not always mean finding words that remove pain. Reliable company and a practical promise you can keep may be more useful.',
'Offer one specific form of company or help, and let the grieving person choose whether they want it.',
'This fits accompanying someone through loss, rather than taking control of their grief.',
'You do not need perfect words to keep someone company through a hard journey.',
'https://ebible.org/web/RUT01.htm')

case('yusuf-brothers','Islam','Yusuf meets the brothers who wronged him','Quran','Surah Yusuf 12:58–92','Scripture narrative','betrayal|family_repair','People close to me hurt me and now want to reconnect.',
'Yusuf’s brothers come to Egypt without recognising him. Several encounters follow before he reveals himself. In 12:90–92, the reunion includes recognition of wrong and Yusuf’s response to it.',
'The passage places patience, wrongdoing and forgiveness inside a long and difficult family history.',
'You can think carefully about what reconnection would mean. This story is not an instruction to ignore danger or grant another person immediate access to your life.',
'Name what you would need for a safe conversation before deciding whether to have one.',
'This fits renewed contact after betrayal, rather than a simple disagreement.',
'Their past action need not choose every part of your response today.',
'https://quran.com/12/90-92')
case('yaqub-grief','Islam','Yaqub names his sorrow before Allah','Quran','Surah Yusuf 12:83–87','Scripture narrative','grief_separation|bereavement','I feel ashamed that I still feel deep sorrow.',
'Yaqub grieves the separation from his sons. The passage describes the depth of his sadness and his turning with sorrow toward Allah, while he also tells his sons not to give up their search.',
'Sorrow and hope are present in the same passage; sadness is not treated as proof that faith is absent.',
'You can bring grief honestly into prayer and conversation. Yaqub’s circumstances are not the same as every loss, and the story’s reunion is not promised to each reader.',
'Put your sorrow into honest words in prayer or with a trusted listener, without forcing yourself to sound cheerful.',
'This fits the feeling that sorrow and hope cannot exist together.',
'You can carry hope without hiding the sorrow you still feel.',
'https://quran.com/12/83-87')
case('yunus-distress','Islam','Yunus calls for help in distress','Quran','Al-Anbiya 21:87–88; As-Saffat 37:139–148','Scripture narrative','regret|feeling_trapped','I regret a decision and feel trapped by what followed.',
'The Quran describes Yunus in darkness calling to Allah, acknowledging wrong, and being delivered from distress. The fuller account places this within his story as a messenger.',
'The passage connects honest acknowledgment with turning for help, rather than hiding in the mistake.',
'If you regret something you did, begin with what is true and with support. This is not a claim that every hardship is caused by wrongdoing.',
'Name the part you can take responsibility for and one person who can help you plan a repair.',
'This fits regret about a choice, not blaming yourself for someone else’s harm.',
'An honest request for help can be a new beginning inside a difficult situation.',
'https://quran.com/21/87-88')
case('hajar-search','Islam','Hajar keeps looking for help','Sahih al-Bukhari','Hadith 3364','Hadith narrative','urgent_need|caregiving_alone','I feel alone while trying to care for someone who depends on me.',
'The hadith describes Hajar searching between Safa and Marwa after the water has run out. She looks for help repeatedly while caring for her child. The account then tells of the water at Zamzam.',
'The narrative includes active searching as well as trust in Allah.',
'You do not have to wait silently for help. Looking for a practical route to support is compatible with faith; the miracle is not a promise about a particular modern outcome.',
'Identify the nearest real source of help and make one clear request about the urgent need.',
'This fits a caregiver facing a concrete need alone. Its source is a hadith, not a Quranic verse.',
'Seeking help is an act of care, not a failure of trust.',
'https://sunnah.com/bukhari:3364')

case('moses-shepherd','Sufi wisdom','Moses learns to hear the shepherd’s devotion','Masnavi','Book II, story of Moses and the Shepherd','Spiritual parable','fear_judgment|imperfect_expression','I am afraid that my honest words are not good enough.',
'In Rumi’s parable, Moses rebukes a shepherd’s very human way of speaking to God. A divine rebuke then challenges Moses for separating a devoted person from God. Moses goes back to find the shepherd.',
'The parable contrasts attention to outward wording with attention to sincere devotion.',
'If fear of saying things perfectly is stopping an honest conversation or prayer, begin with sincere words. This is Rumi’s spiritual parable, not an account from the Quran.',
'Write what you honestly mean before editing it to impress someone.',
'This fits shame about imperfect expression, not permission to disregard another person’s beliefs.',
'Your sincere meaning deserves to be heard before your wording is judged.',
'https://sacred-texts.com/isl/masnavi/msn02.htm')
case('lover-watchman','Bahá’í Faith','The frightened lover sees only part of the path','The Seven Valleys','Valley of Knowledge, lover and watchman story','Spiritual parable','uncertainty|blocked_path','An obstacle has made me feel that there is no way forward.',
'A lover searching for his beloved is pursued by a watchman. Trying to escape, he climbs a wall into a garden and finds the person he sought. The story is used to explore the limits of a narrow view of events.',
'The parable invites a wider perspective; it does not say readers can already know the purpose of every painful event.',
'You need not call the obstacle good. You can still ask whether another route or a piece of information is missing.',
'List one route that is blocked and two alternatives you have not yet checked.',
'This fits feeling that one blocked route means every route is closed.',
'Not seeing a way yet is different from knowing that no way exists.',
'https://www.bahai.org/library/authoritative-texts/bahaullah/call-divine-beloved/')
case('bahai-justice','Bahá’í Faith','Justice asks for your own careful seeing','The Hidden Words','Arabic, number 2','Scriptural teaching','judged_by_group|comparison','Other people’s opinions are deciding how I see myself.',
'This passage praises justice and asks the reader to see with their own eyes and know through their own understanding, rather than depending entirely on another person’s view.',
'Its setting is a teaching about justice and discernment, not a promise of social approval.',
'Separate what you actually know from what others have assumed. A fair view can include both your effort and what still needs work.',
'Write one judgment you have accepted and the evidence that supports or challenges it.',
'This fits borrowed judgments and comparison, rather than every form of sadness.',
'A fair view of your life can be wider than the opinion you have been given.',
'https://www.bahai.org/library/authoritative-texts/bahaullah/hidden-words/')

case('kisa-loss','Buddhism','Kisa Gotami searches for a house untouched by death','Dhammapada Commentary','Book VIII, story 13, associated with verse 114','Commentarial narrative','bereavement','I feel that nobody understands what losing this person is like.',
'In the commentary’s story, Kisa Gotami seeks help after her child dies. She is asked to bring mustard seed from a home where no one has died. Visiting homes reveals that other families have also known loss.',
'The story moves from isolated grief toward recognition of shared mortality. It belongs to commentary, not the wording of Dhammapada verse 114 itself.',
'Knowing that grief is shared need not make your particular loss smaller. It may give you someone beside whom you can carry it.',
'Look for one person or group where you can speak about the person you lost without being rushed.',
'This is specifically about death and the loneliness of grief.',
'Your grief is your own, but you do not have to carry it entirely alone.',
'https://ancient-buddhist-texts.net/English-Texts/Dhamma-Verses-Comm/08-13.htm')
case('angulimala-change','Buddhism','Angulimala stops causing harm','Majjhima Nikaya','MN 86, Angulimala Sutta','Scripture narrative','regret|second_chance','I want to change but feel defined by what I did before.',
'Angulimala has caused grave harm. After meeting the Buddha, he abandons violence and enters a different way of life. The sutta also describes consequences he still faces; change does not erase the past.',
'The narrative distinguishes stopping harm from escaping responsibility.',
'Your situation may be very different. The relevant lesson is to make change visible through conduct and repair, not to ask others to forget what happened.',
'Choose one harmful pattern to stop and one repair you can begin safely.',
'This fits responsibility for your own past conduct, not guilt imposed on you unfairly.',
'Real change can begin without pretending that the past never happened.',
'https://www.accesstoinsight.org/tipitaka/mn/mn.086.than.html')
case('buddha-insult','Buddhism','The Buddha does not return an insult','Samyutta Nikaya','SN 7.2, Akkosa Sutta','Teaching dialogue','insult|argument','Someone insults me and I feel pulled into fighting back.',
'A brahmin angrily abuses the Buddha. The Buddha asks what happens to offered food when a guest does not accept it, and uses that comparison to explain why he does not join the exchange of abuse.',
'The dialogue shows refusal to add another round of anger.',
'You can decline an insult’s invitation to fight while still protecting your boundary. Silence is not the only option; a brief limit or leaving can also be a choice.',
'Prepare one sentence such as: I will discuss the issue, but not while I am being insulted.',
'This fits provocation and an escalating argument, not a requirement to tolerate abuse.',
'An insult does not have to choose your next words.',
'https://www.accesstoinsight.org/tipitaka/sn/sn07/sn07.002.budd.html')
case('rahula-mirror','Theravada Buddhism','Rahula is taught to review an action','Majjhima Nikaya','MN 61, Ambalatthika-Rahulovada Sutta','Teaching dialogue','repeat_mistake|habits','I keep repeating something I know I should change.',
'The Buddha asks Rahula what a mirror is for, then teaches him to examine actions before, during and after doing them, including whether they cause harm. Mistakes become occasions for acknowledgment and restraint.',
'The teaching gives a sequence for review, not only an instruction to have more willpower.',
'Look for the moment before the pattern starts and the point where you can interrupt it. Review what happened without hiding the result.',
'Write your trigger, one interruption you can try and a time to review the attempt.',
'This fits a repeated action you want to change.',
'A pattern can become clearer when you learn where to pause it.',
'https://www.accesstoinsight.org/tipitaka/mn/mn.061.than.html')
case('two-arrows','Theravada Buddhism','The Buddha distinguishes two kinds of pain','Samyutta Nikaya','SN 36.6, Sallatha Sutta','Teaching illustration','rumination','A problem happened and I keep adding fears and harsh judgments to it.',
'The Buddha compares bodily pain with being struck by an arrow, and the added distress of an untrained response with a second arrow. The illustration distinguishes the event from further reactions around it.',
'The teaching makes a distinction; it is not a reason to blame someone for suffering.',
'Notice which part of the difficulty is happening now and which part is a repeated prediction or self-attack. Both deserve care, but they may need different responses.',
'Write one fact about the event and one fear you are adding. Choose which needs action and which needs gentle attention.',
'This fits rumination after a setback, rather than claiming that grief or illness is merely an attitude.',
'You may not choose the first hurt, but you can begin to notice what is being added around it.',
'https://www.accesstoinsight.org/tipitaka/sn/sn36/sn36.006.than.html')

case('lotus-poor-son','Mahayana Buddhism','The son is helped to grow into what he cannot yet believe','Lotus Sutra','Chapter 4, Faith and Understanding','Scriptural parable','self_doubt|learning','An opportunity feels too big and I do not believe I belong there.',
'In the parable, a poor son encounters his wealthy father without recognising the relationship. He is frightened by what seems beyond him. The father approaches gradually, allowing familiarity and confidence to develop before disclosing the inheritance.',
'The parable explains gradual teaching in a Buddhist setting, not material wealth for every believer.',
'An unfamiliar role may need a supported beginning. You can ask for stages, explanation and practice rather than deciding immediately that you do not belong.',
'Ask for one smaller responsibility through which you can learn the larger role.',
'This fits feeling unready for an unfamiliar opportunity.',
'You can grow into a responsibility through steps rather than one sudden leap.',
'https://sacred-texts.com/bud/lotus/lot04.htm')
case('never-disparaging','Mahayana Buddhism','Never Disparaging keeps respect without staying within reach of harm','Lotus Sutra','Chapter 20, Bodhisattva Never Disparaging','Scriptural narrative','insult|judged_by_group','People mock me and I am starting to lose respect for myself.',
'The bodhisattva Never Disparaging expresses respect for others’ potential. Some respond with hostility. The narrative describes him withdrawing to a distance while continuing his respectful message.',
'Respect is paired with movement away from immediate harm.',
'You can refuse to make cruelty your measure of worth and still take practical distance. The story does not ask you to remain available to mistreatment.',
'Choose one boundary or source of support that will reduce your exposure to the mockery.',
'This fits contempt and ridicule, rather than an ordinary difference of opinion.',
'You can protect your dignity without learning to treat yourself with their contempt.',
'https://nichiren.info/buddhism/lotussutra/text/chap20.html')
case('dogen-cook','Soto Zen','Dogen learns from an older cook','Tenzo Kyokun','Account of the cook drying mushrooms','Monastic teaching narrative','work_unseen|procrastination','The work in front of me feels too ordinary to matter.',
'Dogen sees an older monastery cook drying mushrooms in the heat. When he asks why another person cannot do it or why it cannot wait, the cook points him back to this person’s responsibility and this time for doing it.',
'The encounter challenges the idea that ordinary work is separate from practice.',
'This is not advice to ignore age, heat or health. The useful question is whether you are dismissing a necessary act only because it is not impressive.',
'Choose one overlooked task and name the person or purpose it serves before starting.',
'This fits dismissing everyday work, not the need for medical rest or relief from overload.',
'Ordinary work can carry real care even when nobody applauds it.',
'https://www.sotozen.com/eng/library/stories/vol07.html')
case('dogen-boat','Soto Zen','The moving shore changes when attention changes','Shobogenzo','Genjokoan, boat-and-shore illustration','Philosophical illustration','fixed_assumption|comparison','I am treating my first view of the situation as the whole truth.',
'Dogen describes a person in a boat who looks at the shore and may think the shore is moving. Looking closely at the boat changes the understanding. The illustration appears in a discussion of self and experience.',
'The image asks the reader to examine the standpoint from which an impression is formed.',
'Before accepting a painful comparison or assumption, ask what your view leaves out. Another standpoint may reveal something important without making your feelings unreal.',
'Write your first conclusion and one fact you would need to check before treating it as certain.',
'This fits a fixed interpretation or comparison, not evidence that every problem is imaginary.',
'Your first view can be real without being complete.',
'https://www.sotozen.com/eng/practice/sutra/index.html')

case('cook-ding','Daoism','Cook Ding stops forcing his way through','Zhuangzi','Chapter 3, Nourishing Life; Cook Ding','Philosophical story','learning|difficult_task','I am working harder but the same task still feels clumsy.',
'Cook Ding explains his skill to Lord Wenhui. Rather than force the knife against everything, he follows the structure he has learned to perceive. At a difficult place, he becomes careful and moves slowly.',
'The story joins long practice with attention to the task’s actual structure.',
'More force may not be the missing ingredient. Look for the part of the process you do not yet understand and practise that part slowly.',
'Break the task into steps. Ask an experienced person to watch the step where you get stuck.',
'This fits learning a difficult skill, not a guarantee that effort is unnecessary.',
'A better way of seeing the task may help more than another round of forcing it.',
'https://ctext.org/zhuangzi/nourishing-the-lord-of-life')
case('wheelwright-bian','Daoism','The wheelwright explains what a book alone cannot give','Zhuangzi','Chapter 13, The Way of Heaven; wheelwright Bian','Philosophical dialogue','learning|procrastination','I keep collecting advice but never feel ready to practise.',
'Wheelwright Bian speaks with Duke Huan about skill. He describes a feel for his work that cannot be fully handed over in words, even though it can be learned through doing.',
'The dialogue points to a difference between descriptions of a skill and embodied practice.',
'Advice may help, but another explanation is not always a substitute for a safe first attempt and useful feedback.',
'Choose a small practice attempt and decide what feedback would help you learn from it.',
'This fits preparation becoming a substitute for practice.',
'Some understanding becomes available only when you begin to practise.',
'https://ctext.org/zhuangzi/tian-dao')
case('confucius-two-students','Confucianism','Two students ask the same question and receive different guidance','Analects','11.22; Zilu and Ranyou','Teaching dialogue','career_choice|comparison','Other people tell me to copy the advice that worked for someone else.',
'Zilu and Ranyou ask whether to act immediately on what they have learned. Confucius restrains one and urges the other forward. He explains that one tends to rush while the other tends to hold back.',
'The dialogue makes guidance responsive to the person’s actual tendency.',
'Before copying someone else’s next step, ask whether your difficulty is rushing without thought or waiting after enough thought.',
'Name which tendency is stronger in this decision. Choose one action that balances it.',
'This fits conflicting advice and comparison; it does not offer the same answer to everyone.',
'Good guidance can fit your situation without looking like someone else’s path.',
'https://ctext.org/analects/xian-jin')
case('confucius-chen','Confucianism','Confucius is questioned during hardship in Chen','Analects','15.2','Teaching dialogue','unfair_setback|values_pressure','A setback is making me wonder whether I should abandon my values.',
'The group is short of food in Chen. Zilu asks whether a worthy person can also face such difficulty. Confucius distinguishes facing hardship from letting hardship dissolve one’s standards.',
'The conversation rejects the idea that good conduct guarantees an easy life.',
'A setback is not proof that your values were pointless. You can reconsider a plan without deciding that every principle must be discarded.',
'Name one value you want to keep and one practical part of your plan you are willing to change.',
'This fits pressure to give up a principle after misfortune.',
'A difficult season can challenge your plan without proving that your values were a mistake.',
'https://ctext.org/analects/wei-ling-gong')

case('sikh-no-stranger','Sikhism','A hymn opens a different way of seeing others','Guru Granth Sahib','Ang 1299; Guru Arjan’s hymn beginning Na ko bairi nahi begana','Scriptural hymn','judged_by_group|friendship_distance','I have begun to see everyone around me as an enemy.',
'In this hymn, Guru Arjan describes a changed relationship with others: no enemy and no stranger, within a vision shaped by the Divine. It is a spiritual perspective, not a report of a modern social dispute.',
'The hymn loosens a fixed division between oneself and others.',
'You can question whether every person has become an enemy in your mind while still recognising real danger and keeping necessary boundaries.',
'Choose one safe interaction in which you can replace an assumption with a genuine question.',
'This fits blanket suspicion or a hardened social division, not a demand to trust unsafe people.',
'You can leave room for a human connection without giving up wise boundaries.',
'https://www.srigranth.org/servlet/gurbani.gurbani?Action=Page&Param=1299')
case('sikh-humility','Sikhism','Sweetness and humility are presented as strengths','Guru Granth Sahib','Ang 470; Asa Ki Var, salok on sweetness and humility','Scriptural teaching','argument|speaking_fear','I want to speak clearly without making a family argument worse.',
'The salok praises sweetness and humility as qualities with real value. It appears within Asa Ki Var’s examination of conduct, not as advice to hide the truth.',
'The teaching directs attention to the manner in which one speaks and lives.',
'A respectful tone does not need to erase your request. You can name the issue plainly without humiliating the other person.',
'Prepare one sentence that describes the issue and one that says what you need, without an insult.',
'This fits the way a difficult conversation is being handled.',
'You can be clear without making another person small.',
'https://www.srigranth.org/servlet/gurbani.gurbani?Action=Page&Param=470')

case('nemi-wedding','Jainism','Nemi changes course when he sees the cost','Uttaradhyayana Sutra','Chapter 22, story of Aristanemi and Rajimati','Scripture narrative','values_pressure|conflicting_values','Something I am expected to do conflicts with my conscience.',
'On the way to his wedding, Aristanemi learns that animals are being held to be killed for the feast. The account describes his compassion for them and his decision to turn toward renunciation.',
'The story places the harm to other beings ahead of the momentum of a public occasion.',
'Your choice need not copy Nemi’s renunciation. The useful question is whether pressure and preparations are making a serious ethical concern harder to hear.',
'Name the concern and one lower-harm alternative you can discuss before committing.',
'This fits a conflict of conscience under social pressure, not ordinary dislike of a task.',
'You are allowed to examine the cost of a path even when others expect you to continue.',
'https://sacred-texts.com/jai/sbe45/sbe4524.htm')
case('jain-leaf','Jainism','A falling leaf makes delay visible','Uttaradhyayana Sutra','Chapter 10, The Leaf of the Tree','Teaching illustration','procrastination|habits','I keep waiting for a perfect time to make an important change.',
'The teaching compares human life with a leaf that falls and repeatedly urges Gautama not to remain careless. Its original setting is commitment to spiritual practice.',
'The image challenges indefinite delay in the face of changing conditions.',
'This is not a demand to panic or fill every hour. Apply it to one change you already know matters and have repeatedly postponed.',
'Choose a first action small enough to do today and set a clear time for it.',
'This fits repeated postponement, rather than exhaustion that needs care.',
'A small beginning today can be more faithful to your intention than another perfect plan.',
'https://sacred-texts.com/jai/sbe45/sbe4512.htm')

case('zoro-exclusion','Zoroastrianism','Zarathushtra asks where he can find support','Avesta','Yasna 46.1–2','Scriptural hymn','family_rejection|feeling_alone','I feel rejected by my community and do not know where to turn.',
'The speaker, understood in the tradition as Zarathushtra, asks where he should go when excluded from family and community. He names his lack of resources and turns to Ahura Mazda for support.',
'The hymn voices need and rejection directly instead of disguising them as strength.',
'Feeling unsupported is a reason to look for real support, not a final verdict on your worth. Faith and a practical search for allies can be held together.',
'Name one safe person or community outside the rejecting circle whom you can approach.',
'This fits exclusion and a lack of support, not a random career problem.',
'Being rejected by one circle does not mean that you have no place to turn.',
'https://www.avesta.org/yasna/index.html')
case('zoro-choices','Zoroastrianism','A hymn asks each listener to choose thoughtfully','Avesta','Yasna 30.2–3','Scriptural teaching','conflicting_values|big_decision','I am being pushed to choose before I have thought clearly.',
'The hymn calls its listeners to hear and consider, then choose with understanding. The surrounding verses contrast better and harmful ways of thought, word and deed.',
'Choice is linked to discernment and ethical responsibility.',
'You can ask for the facts and the time needed for a serious decision. A considered answer need not be the loudest or fastest one.',
'Write what you know, what you need to find out and which value the choice should protect.',
'This fits a pressured ethical decision, not a promise that certainty will be complete.',
'A thoughtful pause can be part of a strong choice.',
'https://www.avesta.org/yasna/index.html')

case('epictetus-bath','Stoicism','Epictetus prepares a student for the bathhouse','Enchiridion','Section 4','Philosophical teaching','anger_reaction|fear_ahead','Small predictable frustrations keep ruining my day.',
'Epictetus asks a person planning a bath to remember what can happen there: splashing, crowding and rude behaviour. He links the plan to bathe with the intention to keep one’s conduct steady.',
'The teaching prepares for friction before it arrives.',
'If the same setting repeatedly frustrates you, decide in advance how you want to respond. This does not mean giving up action when a problem can be fixed.',
'Name one predictable irritation and prepare a brief response or exit plan before entering the situation.',
'This fits recurring minor friction, not serious harm that requires protection.',
'A familiar frustration can be prepared for instead of being allowed to surprise you each time.',
'https://classics.mit.edu/Epictetus/epicench.html')
case('epictetus-handles','Stoicism','A brother’s action is not the only handle','Enchiridion','Section 43','Philosophical illustration','family_repair|fixed_assumption','One painful incident has become the only way I see a family member.',
'Epictetus describes an affair as having two handles and gives the example of a brother behaving wrongly. He contrasts holding only the wrong with also considering the relationship.',
'The illustration asks how the way one holds an event affects the response.',
'You can consider a wider picture without excusing the act. In an unsafe relationship, distance can still be necessary.',
'Separate the action you object to from the whole history. Decide which boundary or conversation is appropriate now.',
'This fits a narrowed view of a family conflict, not a requirement to reconcile.',
'A wider view can help you choose a response without making the wrong disappear.',
'https://classics.mit.edu/Epictetus/epicench.html')
case('marcus-morning','Stoicism','Marcus writes to himself when getting up feels difficult','Meditations','Book 5, section 1','Personal philosophical notes','procrastination|work_unseen','I keep putting off work that I know matters.',
'Marcus Aurelius writes a morning reminder to himself about getting up for human work. He weighs the appeal of comfort against the activity appropriate to human life.',
'The passage is a personal prompt toward meaningful activity, not a diagnosis of anyone who cannot get out of bed.',
'For ordinary avoidance, reconnect the task with the person or purpose it serves. Exhaustion, illness and depression may call for a different kind of care.',
'Name why the task matters and begin with five manageable minutes.',
'This fits avoidant delay when you have capacity, not a reason to shame yourself for being unwell.',
'You can begin with the purpose of the work, not a demand to feel motivated first.',
'https://classics.mit.edu/Antoninus/meditations.5.five.html')

case('socrates-speaking','Greek philosophy','Socrates chooses plain speech before the court','Apology','17a–18a','Philosophical account','speaking_fear|fear_judgment','I am afraid I must sound impressive to be taken seriously.',
'At the opening of Plato’s account, Socrates distinguishes persuasive display from speaking truthfully. He asks the court to attend to whether what he says is just, rather than the polish of his language.',
'The scene contrasts an account’s substance with its presentation.',
'Preparation matters, but you need not copy an impressive persona to explain what you know. The modern parallel is limited; an interview is not Socrates’ trial.',
'Prepare your main point and one clear example before polishing the wording.',
'This fits fear about how you sound in a serious conversation.',
'You can make your meaning clear without borrowing someone else’s voice.',
'https://classics.mit.edu/Plato/apology.html')
case('socrates-crito','Greek philosophy','Socrates asks Crito to examine the reason for escape','Crito','46b–49e','Philosophical dialogue','values_pressure|big_decision','People are urging me to act, but I am unsure the action is right.',
'Crito urges Socrates to escape from prison. Socrates asks them to examine the argument rather than decide from fear of public opinion, and discusses whether one should answer wrongdoing with wrongdoing.',
'The dialogue makes the reasons for a choice central even under pressure.',
'You do not need to adopt every conclusion of the dialogue. Its useful method is to test the proposed action against reasons you can defend.',
'Write the strongest reason for the action and the strongest ethical objection to it before deciding.',
'This fits pressure to act against a considered value.',
'Pressure from others need not replace your own careful examination.',
'https://classics.mit.edu/Plato/crito.html')

case('kural-deliberation','Tamil ethical wisdom','Tiruvalluvar places thought before commitment','Tirukkural','Chapter 47, especially couplet 467','Ethical teaching','big_decision|career_choice|conflicting_values','I am about to commit because I feel rushed.',
'In the chapter on acting after deliberation, Tiruvalluvar places careful consideration before undertaking an action. Couplet 467 warns against treating reflection as something to begin only after committing.',
'The teaching concerns the timing of thought in relation to action.',
'For an important choice, look at the conditions and consequences before giving your agreement. This is different from postponing forever after enough thought.',
'List two likely consequences and one missing fact you should check before committing.',
'This fits a rushed commitment, rather than general low confidence.',
'You can give an important decision the thought it deserves before saying yes.',
'https://www.projectmadurai.org/pm_etexts/utf8/pmuni0665.html')
case('kural-speech','Tamil ethical wisdom','Kind speech is tested against needless harshness','Tirukkural','Chapter 10, couplets 91–100','Ethical teaching','argument|supporting_grief','I need to say something difficult without hurting someone needlessly.',
'This chapter examines sincere and pleasant speech. It values words shaped by care and contrasts them with harshness chosen when a kinder way is available.',
'The teaching addresses how truth and care can shape speech together.',
'You can keep the necessary truth while removing a needless insult or humiliation. Kindness does not require hiding the issue.',
'Write the sentence you need to say, then remove the part that attacks the person rather than names the problem.',
'This fits the wording of a difficult conversation, not an obligation to please everyone.',
'A clear truth can be spoken without adding an unnecessary wound.',
'https://www.projectmadurai.org/pm_etexts/utf8/pmuni0665.html')

case('hermes-questions','Hermetic philosophy','The narrator begins by asking what he wants to understand','Corpus Hermeticum','Treatise I, Poimandres, opening dialogue','Visionary teaching dialogue','purpose|learning','I feel lost because I have too many unanswered questions.',
'The narrator describes being absorbed in thought when Poimandres appears and asks what he wishes to hear and learn. The dialogue begins with a stated wish to understand existence and the divine.',
'The text frames a spiritual search through questions and instruction.',
'You need not solve your whole life in one question. Give your search a clear starting point without treating this visionary dialogue as a modern psychological method.',
'Choose the question that most affects your next decision and one trustworthy source or person through whom to examine it.',
'This fits an unfocused search for understanding, rather than a concrete emergency.',
'A sincere question can give a large search a place to begin.',
'https://sacred-texts.com/chr/herm/hermes01.htm')

case('ptahhotep-listener','Ancient Egyptian wisdom','An official is told to hear the whole concern','Instruction of Ptahhotep','Teaching on receiving a petitioner','Wisdom instruction','helping_someone|argument','Someone close to me says I never really listen.',
'The instruction advises a person receiving a petitioner to listen patiently to the concern. Being heard is treated as important, not merely reaching a quick decision.',
'Its original setting concerns authority and the treatment of a person bringing a complaint.',
'In a personal conversation, it may help to understand the full concern before defending yourself or giving advice.',
'Ask the person to finish their account, then check your understanding in one sentence before replying.',
'This fits a problem of feeling unheard, rather than assuming every complaint is correct.',
'Listening fully can be an action, not just a pause before your answer.',
'https://sacred-texts.com/egy/woe/woe06.htm')
case('eloquent-peasant','Ancient Egyptian wisdom','A wronged traveller keeps asking for a fair hearing','The Eloquent Peasant','Khunanup’s petitions to Rensi','Literary wisdom narrative','unfair_setback|speaking_fear','I have been treated unfairly and struggle to explain what happened.',
'A peasant travelling with goods is wronged by a man who takes his property. He brings his complaint to an official, Rensi, and gives a series of appeals for justice. The narrative examines power and the obligation to hear a wronged person.',
'The story makes a particular injury visible through clear and sustained speech.',
'A useful modern step is to set out what happened and what response you seek. The story is not a promise that persistence always brings a fair outcome.',
'Write the events in order, keep the relevant records and state the specific response you are asking for.',
'This fits the difficulty of presenting a grievance clearly.',
'A clear account can help you give your concern the voice it deserves.')

case('maya-dark-house','K’iche’ Maya tradition','The Hero Twins face a test with resourcefulness','Popol Vuh','Hero Twins in Xibalba, the Dark House trial','Sacred narrative','difficult_task|blocked_path','The obvious way of solving a problem is not working.',
'In the Dark House trial, the Hero Twins face demands about keeping torches and cigars burning without consuming them. The narrative describes how they use resourcefulness to meet the test rather than follow the obvious route.',
'This episode belongs to the twins’ larger struggle in Xibalba.',
'Before repeating a failed approach, ask which condition you have assumed must be met in only one way. Do not apply the story as permission for harmful deception.',
'Name the real requirement of your problem and one safe alternative method you can test.',
'This fits being stuck on a method, not a claim that every obstacle has an easy trick.',
'A blocked method does not always mean the goal itself is closed.',
'https://sacred-texts.com/nam/pvuheng.htm')

case('amaterasu-cave','Shinto','The gods work together outside Amaterasu’s cave','Kojiki','Book I, the Heavenly Rock Cave episode','Sacred narrative','withdrawal|helping_someone','After a painful conflict, I want to shut everyone out.',
'After Susanoo’s disruptive actions, Amaterasu withdraws into the rock cave and the world loses her light. The other deities gather and work out a way to draw her attention outward, with ritual, laughter and a mirror.',
'The episode is a sacred account of withdrawal and a collective response, not a clinical account of depression.',
'After conflict, distance may protect you. When you are ready, one safe connection may be a gentler step than demanding a full return to normal.',
'Choose one safe person and one small form of contact that you can accept without pressure.',
'This fits withdrawal after hurt; it does not mean you owe others a cheerful performance.',
'You can return to connection in a way that leaves room for the hurt you have felt.',
'https://sacred-texts.com/shi/kojiki.htm')
case('white-hare','Shinto','Okuninushi asks the injured hare what happened','Kojiki','Book I, the White Hare of Inaba episode','Sacred narrative','helping_someone|fixed_assumption','My advice is not helping a friend who is hurting.',
'The hare has received advice that worsens its condition. Okuninushi encounters it, asks why it is suffering, hears its account and responds differently. The story contrasts careless treatment with attentive help.',
'The narrative’s treatment details are not medical instructions for a reader.',
'The useful parallel is to learn what happened before repeating familiar advice. Ask what your friend needs and recognise when skilled help is needed.',
'Ask what has already been tried and whether your friend wants listening, practical help or help finding an appropriate professional.',
'This fits help that has become advice without understanding.',
'A caring question may help more than advice given too quickly.',
'https://sacred-texts.com/shi/kojiki.htm')

case('nephi-bow','Latter-day Saint Christianity','Nephi makes a new bow after the old one breaks','Book of Mormon','1 Nephi 16:18–32','Scripture narrative','method_failure|blocked_path','A tool or plan I depended on has failed.',
'Nephi’s bow breaks while the travelling family needs food. Amid the group’s distress, he makes a wooden bow and an arrow, then asks his father where he should go to obtain food.',
'The episode combines making a practical replacement with seeking guidance.',
'When the old method fails, separate the need from the tool that used to meet it. A workable replacement may be enough for the next stage.',
'Write the need the failed tool or plan served. List one available substitute and the guidance you need to use it.',
'This fits a failed method or resource, not a promise that the loss has no cost.',
'A failed tool can call for a new method rather than the end of your effort.',
'https://www.churchofjesuschrist.org/study/scriptures/bofm/1-ne/16?lang=eng')
case('alma-regret','Latter-day Saint Christianity','Alma tells of guilt, remembrance and turning for help','Book of Mormon','Alma 36:6–21','Scripture narrative','regret|second_chance','I feel overwhelmed by regret about what I have done.',
'Alma recounts distress over his wrongdoing and his remembrance of teaching about Jesus Christ. He describes turning to Christ for mercy and a profound change in his experience.',
'The account presents repentance within faith, not denial of the wrong that caused the remorse.',
'You can seek spiritual help while also considering what repair and changed conduct are possible. The passage is not a promise of instant relief for every reader.',
'Speak honestly with a trusted spiritual adviser or support person about one part you can take responsibility for.',
'This fits remorse about your own conduct, not shame imposed by someone else.',
'Honest remorse can be a turning point toward help and repair.',
'https://www.churchofjesuschrist.org/study/scriptures/bofm/alma/36?lang=eng')


case('rama-mourns','Hinduism','Rama grieves when he hears of his father’s death','Valmiki Ramayana','Ayodhya Kanda, Sargas 102–103','Scripture narrative','bereavement','I feel weak because I cannot stop grieving.',
'Bharata tells Rama of Dasharatha’s death. Rama is overcome by the news, grieves with those around him and performs the water offering for his father. The story does not present him as untouched by loss.',
'The episode gives grief, family and remembrance a place even in the life of Rama.',
'Your grief does not make you less worthy or less faithful. You can let others stand beside you and choose a form of remembrance that fits your beliefs.',
'Ask one trusted person to share a memory or sit with you without trying to fix the feeling.',
'This fits mourning a death, rather than treating every disappointment as the same loss.',
'Feeling a loss deeply does not mean that your strength has disappeared.',
'https://www.valmikiramayan.net/utf8/ayodhya/sarga103/ayodhyaroman103.htm')
case('musa-madyan','Islam','Musa begins again far from home','Quran','Al-Qasas 28:21–28','Scripture narrative','role_loss|urgent_need','I have to start again and do not know where help will come from.',
'Musa reaches Madyan after fleeing Egypt. At the well he helps two women water their animals, then turns to Allah with a prayer of need. A later invitation leads to shelter and an agreement about work.',
'The account joins honest need, useful action and help received through other people.',
'You need not solve the whole future at once. Identify what you need now and an available action or contact. The story is not a promise of the same outcome for every reader.',
'Name one immediate need and contact one real source of support for it today.',
'This fits beginning again after losing security, rather than a general complaint about motivation.',
'Needing a new beginning does not mean you have no useful next action.',
'https://quran.com/28/21-28')

assert len({c['id'] for c in cases})==len(cases)
assert all(c['story'] and c['why'] and c['book'] and c['reference'] for c in cases)
out=R/'assets/episodes.json';out.write_text(json.dumps(dict(version=3,principle='Specific situation first; source episode next; original application kept separate.',coverage='Bounded reviewed collection; not exhaustive worldwide scripture coverage.',episodes=cases),ensure_ascii=False,indent=2),encoding='utf-8')
notes=R.parent/'episode-library';notes.mkdir(exist_ok=True)
for tradition in sorted({c['tradition'] for c in cases}):
 text=[tradition,'Source-based retellings; original applications are not scripture quotations.','']
 for c in cases:
  if c['tradition']!=tradition:continue
  text += [c['title'],'Source: '+c['book']+' — '+c['reference'],'Type: '+c['source_kind'],'Situation: '+c['example'],'What happened: '+c['story'],'Teaching: '+c['teaching'],'Why it fits: '+c['why'],'Application: '+c['application'],'Try: '+c['step'],'']
 (notes/(tradition.replace('/','-').replace(' ','_')+'.txt')).write_text('\n'.join(text),encoding='utf-8')
print('EPISODES',len(cases),'TRADITIONS',len({c['tradition'] for c in cases}))
